    print(f"{name:16s} {r['n_states']:7d} {r['effective_information']:8.3f} "
          f"{b['effective_information']:8.3f} {r['emergent_complexity']:8.3f} "
          f"{b['emergent_complexity']:8.3f} {b['emergent_complexity_std']:7.3f}")

